 "content": "from collections import Counter


def transform(grid):
    """Fill straight gaps between pairs of marker cells, preserving markers."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    markers = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != background}
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if (r, c) not in markers:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if (r, c) not in markers:
                    out[r][c] = 3
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
